interface.definition:
a!localVariables(
  local!allteams: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1132811"(isActive: true()),
  local!teamids: if(
    a!isNotNullOrEmpty(local!allteams),
    tointeger(
      index(
        local!allteams,
        #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/4c75fc18-2599-4da4-b579-737570b6189c",
        null()
      )
    ),
    tointeger(null())
  ),
  local!orgteam: if(
    a!isNotNullOrEmpty(local!teamids),
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1134349"(orgId: ri!orgid, isActive: true()),
    null()
  ),
  local!orgteamids: if(
    a!isNotNullOrEmpty(local!orgteam),
    tointeger(
      index(
        local!orgteam,
        #"urn:appian:record-field:v1:4eb1fdb2-adfe-4b4b-8a61-ccc9f1f5f947/4889b852-272c-42a8-81e1-414933737923",
        null()
      )
    ),
    tointeger({})
  ),
  local!availableteamids: difference(local!teamids, local!orgteamids),
  local!assignedteamids: local!orgteamids,
  local!teamadd: tointeger({}),
  local!teamsremove: tointeger({}),

  #"SYSTEM_SYSRULES_formLayout_v2"(
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "Manage Teams For Organizations",
      secondaryText: "Select The Teams To Add Or Remove From The Organization"
    ),
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {

          /* ── LEFT: AVAILABLE TEAMS ── */
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: "Available Teams",
                contents: {
                  #"SYSTEM_SYSRULES_gridLayout"(
                    headerCells: {
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Team"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Description"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Add")
                    },
                    columnConfigs: {
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE", weight: 3),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE", weight: 3),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "ICON")
                    },
                    rows: #"SYSTEM_SYSRULES_forEach"(
                      items: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1132811"(
                        TeamId: local!availableteamids,
                        isActive: true()
                      ),
                      expression: #"SYSTEM_SYSRULES_gridRowLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_textField"(
                            value: fv!item[
                              #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/d4a08ef8-b6c6-4db9-bb25-3be3a8bcbf2a"
                            ],
                            readOnly: true()
                          ),
                          #"SYSTEM_SYSRULES_textField"(
                            value: fv!item[
                              #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/532d5040-0e9d-4d8c-ae0f-a642f9b22cb6"
                            ],
                            readOnly: true()
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: {
                              #"SYSTEM_SYSRULES_richTextIcon"(
                                icon: "plus-square-o",
                                link: #"SYSTEM_SYSRULES_dynamicLink"(
                                  value: tointeger(
                                    fv!item[
                                      #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/4c75fc18-2599-4da4-b579-737570b6189c"
                                    ]
                                  ),
                                  saveInto: {
                                    a!save(
                                      local!availableteamids,
                                      difference(local!availableteamids, tointeger(save!value))
                                    ),
                                    a!save(
                                      local!assignedteamids,
                                      union(local!assignedteamids, tointeger(save!value))
                                    ),
                                    a!save(
                                      local!teamadd,
                                      union(local!teamadd, tointeger(save!value))
                                    ),
                                    a!save(
                                      local!teamsremove,
                                      difference(local!teamsremove, tointeger(save!value))
                                    )
                                  }
                                ),
                                linkStyle: "INLINE",
                                color: "ACCENT",
                                size: "MEDIUM"
                              )
                            }
                          )
                        }
                      )
                    ),
                    showWhen: a!isNotNullOrEmpty(local!availableteamids),
                    rowHeader: 1
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "No teams available to add.",
                      color: "SECONDARY",
                      style: "EMPHASIS"
                    ),
                    showWhen: a!isNullOrEmpty(local!availableteamids),
                    align: "CENTER"
                  )
                }
              )
            }
          ),

          /* ── RIGHT: ASSIGNED TEAMS ── */


        }
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: "Assigned Teams",
                contents: {
                  #"SYSTEM_SYSRULES_gridLayout"(
                    headerCells: {
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Team"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Description"),
                      #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Remove")
                    },
                    columnConfigs: {
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE", weight: 3),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE", weight: 3),
                      #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "ICON")
                    },
                    rows: #"SYSTEM_SYSRULES_forEach"(
                      items: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1132811"(
                        TeamId: local!assignedteamids,
                        isActive: true()
                      ),
                      expression: #"SYSTEM_SYSRULES_gridRowLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_textField"(
                            value: fv!item[
                              #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/d4a08ef8-b6c6-4db9-bb25-3be3a8bcbf2a"
                            ],
                            readOnly: true()
                          ),
                          #"SYSTEM_SYSRULES_textField"(
                            value: fv!item[
                              #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/532d5040-0e9d-4d8c-ae0f-a642f9b22cb6"
                            ],
                            readOnly: true()
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: {
                              #"SYSTEM_SYSRULES_richTextIcon"(
                                icon: "minus-circle",
                                link: #"SYSTEM_SYSRULES_dynamicLink"(
                                  value: tointeger(
                                    fv!item[
                                      #"urn:appian:record-field:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/4c75fc18-2599-4da4-b579-737570b6189c"
                                    ]
                                  ),
                                  saveInto: {
                                    a!save(
                                      local!availableteamids,
                                      union(local!availableteamids, tointeger(save!value))
                                    ),
                                    a!save(
                                      local!assignedteamids,
                                      difference(local!assignedteamids, tointeger(save!value))
                                    ),
                                    a!save(
                                      local!teamsremove,
                                      union(local!teamsremove, tointeger(save!value))
                                    ),
                                    a!save(
                                      local!teamadd,
                                      difference(local!teamadd, tointeger(save!value))
                                    )
                                  }
                                ),
                                linkStyle: "INLINE",
                                color: "SECONDARY",
                                size: "MEDIUM"
                              )
                            }
                          )
                        }
                      )
                    ),
                    showWhen: a!isNotNullOrEmpty(local!assignedteamids),
                    rowHeader: 1
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "No teams assigned to this organization.",
                      color: "SECONDARY",
                      style: "EMPHASIS"
                    ),
                    showWhen: a!isNullOrEmpty(local!assignedteamids),
                    align: "CENTER"
                  )
                }
              )
            }
          )
        }
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true(),
          loadingIndicator: true(),
          style: "SOLID",
          disabled: and(
            a!isNullOrEmpty(local!teamadd),
            a!isNullOrEmpty(local!teamsremove)
          ),
          saveInto: {
            a!save(ri!teamsToAdd, local!teamadd),
            a!save(ri!teamsToRemove, local!teamsremove),
            a!save(ri!button, #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463")
          }
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          submit: true(),
          validate: false(),
          style: "OUTLINE",
          saveInto: {
            a!save(ri!button, #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469")
          }
        )
      }
    )
  )
)
